import tqdm
from django.db import migrations

#
# consultando o vínculo do servidor pela matrícula
def get_vinculo_by_matricula(apps, matricula):
    Vinculo = apps.get_model('comum.Vinculo')
    Servidor = apps.get_model('rh.Servidor')
    ContentType = apps.get_model('contenttypes.ContentType')
    tipo_relacionamento_servidor = ContentType.objects.get(app_label='rh', model='servidor')
    #
    qs = Servidor.objects.filter(matricula=matricula)
    if qs.exists():
        servidor = qs[0]
        vinculo = Vinculo.objects.get(tipo_relacionamento=tipo_relacionamento_servidor, id_relacionamento=servidor.id)
    else:
        raise ValueError(f'Nenhum servidor encontrado com a matrícula {matricula}')
    #
    return vinculo

#
# Atualizando os dados do ProcessoProgressaoAvaliacao para vincular ao vínculo correto
# com base na matrícula do avaliador (servidor) associado
def atualizar_dados(apps, schema):
    ProcessoProgressaoAvaliacao = apps.get_model('progressoes.ProcessoProgressaoAvaliacao')
    # Iterando sobre todos os processos de progressão de avaliação
    # e atualizando o avaliador_vinculo com o vínculo correto
    for processo in tqdm.tqdm(ProcessoProgressaoAvaliacao.objects.all()):
        #
        # atualizando avaliador
        if processo.avaliador_remover:
            vinculo = get_vinculo_by_matricula(apps, processo.avaliador_remover.matricula)
            processo.avaliador_vinculo = vinculo
            processo.save()
        #
        # atualizando chefe imediato assinante
        if processo.chefe_imediato_assinante_remover:
            vinculo_chefe = get_vinculo_by_matricula(apps, processo.chefe_imediato_assinante_remover.matricula)
            processo.chefe_imediato_assinante_vinculo = vinculo_chefe
            processo.save()


class Migration(migrations.Migration):

    dependencies = [
        ("progressoes", "0018_alter_processoprogressaoavaliacao_options_and_more"),
    ]

    operations = [
        migrations.RunPython(atualizar_dados)
    ]
